sprites.onOverlap(SpriteKind.Enemy, SpriteKind.Projectile, function (sprite, otherSprite) {
    if (boss == sprite) {
        if (otherSprite == sword) {
            otherSprite.destroy(effects.rings, 100)
            statusbars.getStatusBarAttachedTo(StatusBarKind.Health, sprite).value += -2
            if (statusbars.getStatusBarAttachedTo(StatusBarKind.Health, sprite).value < 1) {
                game.gameOver(true)
            }
        } else {
            otherSprite.destroy(effects.disintegrate, 500)
            music.smallCrash.play()
            statusbars.getStatusBarAttachedTo(StatusBarKind.Health, sprite).value += -1
            if (statusbars.getStatusBarAttachedTo(StatusBarKind.Health, sprite).value < 1) {
                game.gameOver(true)
            }
        }
    } else {
        if (otherSprite == sword) {
            otherSprite.destroy(effects.rings, 100)
            statusbars.getStatusBarAttachedTo(StatusBarKind.Health, sprite).value += -2
            if (statusbars.getStatusBarAttachedTo(StatusBarKind.Health, sprite).value < 1) {
                ruppee = sprites.create(assets.image`ruppee`, SpriteKind.rupee)
                ruppee.setPosition(sprite.x, sprite.y)
                ruppee.setScale(0.75, ScaleAnchor.Middle)
                sprite.destroy(effects.ashes, 500)
            }
        } else {
            otherSprite.destroy(effects.disintegrate, 500)
            music.smallCrash.play()
            statusbars.getStatusBarAttachedTo(StatusBarKind.Health, sprite).value += -1
            if (statusbars.getStatusBarAttachedTo(StatusBarKind.Health, sprite).value < 1) {
                ruppee = sprites.create(assets.image`ruppee`, SpriteKind.rupee)
                ruppee.setPosition(sprite.x, sprite.y)
                ruppee.setScale(0.75, ScaleAnchor.Middle)
                sprite.destroy(effects.ashes, 500)
            }
        }
    }
})
