sprites.onOverlap(SpriteKind.Player, SpriteKind.villager, function (sprite, otherSprite) {
    if (controller.A.isPressed()) {
        game.setDialogTextColor(15)
        game.setDialogFrame(img`
            f f f f f f f f f f f f f f f 
            f 2 2 5 2 2 2 5 2 2 2 5 2 2 f 
            f 2 5 2 5 2 5 2 5 2 5 2 5 2 f 
            f 5 2 2 2 5 2 2 2 5 2 2 2 5 f 
            f 2 5 2 d d d d d d d 2 5 2 f 
            f 2 2 5 d d d d d d d 5 2 2 f 
            f 2 5 2 d d d d d d d 2 5 2 f 
            f 5 2 2 d d d d d d d 2 2 5 f 
            f 2 5 2 d d d d d d d 2 5 2 f 
            f 2 2 5 d d d d d d d 5 2 2 f 
            f 2 5 2 d d d d d d d 2 5 2 f 
            f 5 2 2 2 5 2 2 2 5 2 2 2 5 f 
            f 2 5 2 5 2 5 2 5 2 5 2 5 2 f 
            f 2 2 5 2 2 2 5 2 2 2 5 2 2 f 
            f f f f f f f f f f f f f f f 
            `)
        game.showLongText("hello there! got any rupees?", DialogLayout.Bottom)
        if (game.ask("yes", "no")) {
            game.showLongText("if you give me 3 rupees, I'll heal you!", DialogLayout.Bottom)
            if (game.ask("heal for 3 rupees", "decline offer")) {
                if (info.score() > 2) {
                    info.changeScoreBy(-3)
                    health_bar.value += 3
                } else {
                    game.showLongText("you're too poor.", DialogLayout.Bottom)
                }
            } else {
                if (Math.percentChance(10)) {
                    game.showLongText("man, You are STupid!", DialogLayout.Bottom)
                } else {
                    game.showLongText("this is a really good deal. you should probably buy this", DialogLayout.Bottom)
                }
            }
        } else {
            if (info.score() > 0) {
                game.showLongText("Don't lie to me! you have " + info.score() + " rupees!", DialogLayout.Bottom)
            } else {
                game.showLongText("oh wow. you really are broke. kill some monsteres", DialogLayout.Bottom)
            }
        }
        while (mySprite.overlapsWith(rupee_healer)) {
            mySprite.x += 7
        }
        controller.moveSprite(mySprite, 75, 75)
    }
})
